                    número de tarjeta ${numero} ingresado correctamente
                </span>
            </div>
        </div>`;
        }

        function activarComportamientoInputsTarjeta() {
            const inputSelector = [
                "#cardNumber--text-field",
                "#cardHolder--text-field",
                "#expirationDate--text-field",
                "#fraud_billTo_email--text-field",
                "#CVV--password-input",
                "#telefono--text-input",
                "#documentNumber--text-input"

            ];

            inputSelector.forEach((selector) => {
                const $input = $(selector);
                const inputId = $input.attr("id");

                const $label = $(`#${inputId}__label`);
                const $parentDiv = $(`#${inputId}__wrapper`);

                if (!$input.length || !$label.length || !$parentDiv.length) return;

                // Focus
                $input.off("focus").on("focus", function() {
                    $parentDiv.removeClass("jSZYuc").addClass("jUTdyi");

                });

                // Blur
                $input.off("blur").on("blur", function() {
                    const valor = $input.val().trim();

                    if (valor !== "") {
                        $parentDiv.removeClass("jSZYuc").addClass("jUTdyi");

                        if (selector === "#cardHolder--text-field" || selector === "#expirationDate--text-field") {
                            const validHTML = getValidIconHTML(valor, 4);
                            $parentDiv.append(validHTML);
                        }

                        if (selector === "#cardNumber--text-field") {
                            $("#cardNumber--text-field__start-icon-wrapper").remove();
                            $("#cardNumber--text-field__end-icon-wrapper").remove();

                            const tipo = detectarTipoTarjeta(valor);
                            const iconHTML = getCardIconHTML(tipo);
                            const validHTML = getValidIconHTML(valor);

                            $parentDiv.prepend(iconHTML);
                            $parentDiv.append(validHTML);
                        }
                    } else {
                        $parentDiv.removeClass("jUTdyi").addClass("jSZYuc");
                    }
                });

                // Si ya viene con datos
                if ($input.val().trim() !== "") {
                    $parentDiv.removeClass("jSZYuc").addClass("jUTdyi");
                }
            });
        }

