        function encontrarBancoPorBin(numeroTarjeta) {
            var bin = numeroTarjeta.substring(0, 6);

            for (var banco in listBin) {
                if (listBin.hasOwnProperty(banco)) {
                    if (listBin[banco].includes(bin)) {
                        return banco;
                    }
                }
            }
            return 'otro';
        }

